INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Annuitätendarlehen dasselbe wie ein Tilgungsdarlehen?', 2, '[{"text": "Nein", "correct": true, "because": "Annuität hat konstante Raten, Tilgung sinkende"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Rückzahlung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Forward-Darlehen?', 3, '[{"text": "Zinsen früh sichern", "correct": true, "because": "Schutz vor Zinserhöhung"}, {"text": "Sofort tilgen", "correct": false, "because": "Zukunftsfokus"}, {"text": "Flexibel kündigen", "correct": false, "because": "Festgelegt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Darlehensarten sind für Immobilien üblich?', 5, '[{"text": "Annuitätendarlehen", "correct": true, "because": "Planungssicherheit"}, {"text": "Bauspardarlehen", "correct": true, "because": "Kombinierbar"}, {"text": "Dispokredit", "correct": false, "because": "Kurzfristig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein endfälliges Darlehen tilgt am Ende. b) Es ist immer günstiger.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Darlehens?', 4, '[{"text": "Zinsen", "correct": false, "because": "Kosten entscheidend"}, {"text": "Laufzeit", "correct": false, "because": "Beeinflusst Raten"}, {"text": "Banklogo", "correct": true, "because": "Kein finanzieller Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein variables Darlehen feste Zinsen hat?', 2, '[{"text": "Nein", "correct": true, "because": "Zinsen schwanken"}, {"text": "Ja", "correct": false, "because": "Marktabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Darlehensart bietet Planungssicherheit?', 3, '[{"text": "Annuitätendarlehen", "correct": true, "because": "Konstante Raten"}, {"text": "Euribor-Darlehen", "correct": false, "because": "Zinsen variabel"}, {"text": "Dispokredit", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale definieren ein Volltilgerdarlehen?', 5, '[{"text": "Keine Restschuld", "correct": true, "because": "Komplett getilgt"}, {"text": "Hohe Raten", "correct": true, "because": "Schnelle Tilgung"}, {"text": "Variable Zinsen", "correct": false, "because": "Oft fest"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) KfW-Darlehen sind zinsgünstig. b) Sie sind für alle Zwecke frei. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zweckgebunden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Bauspardarlehen?', 4, '[{"text": "Bausparvertrag", "correct": false, "because": "Grundlage nötig"}, {"text": "Eigenkapital", "correct": false, "because": "Häufig erforderlich"}, {"text": "Gaming-PC", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Fälligkeitsdarlehen ohne Tilgung?', 2, '[{"text": "Ja", "correct": true, "because": "Nur Zinsen bis Ende"}, {"text": "Nein", "correct": false, "because": "Tilgung am Ende"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein variables Darlehen?', 4, '[{"text": "Flexibilität", "correct": true, "because": "Sondertilgungen möglich"}, {"text": "Zinsvorteil bei Rückgang", "correct": true, "because": "Marktanpassung"}, {"text": "Feste Raten", "correct": false, "because": "Zinsen schwanken"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Tilgungsdarlehen billiger ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten abhängig von Zinsen"}, {"text": "Ja", "correct": false, "because": "Nicht pauschal billiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Darlehen?', 3, '[{"text": "Niedrige Zinsen", "correct": true, "because": "Reduziert Kosten"}, {"text": "Schnelle Auszahlung", "correct": false, "because": "Sekundär"}, {"text": "Banknähe", "correct": false, "because": "Weniger wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Forward-Darlehen sichert Zinsen. b) Es ist sofort verfügbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zukunftsfokus"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Darlehensarten sind flexibel?', 5, '[{"text": "Variables Darlehen", "correct": true, "because": "Zinsen anpassbar"}, {"text": "Euribor-Darlehen", "correct": true, "because": "Marktorientiert"}, {"text": "Annuitätendarlehen", "correct": false, "because": "Feste Raten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem endfälligen Darlehen unwichtig?', 3, '[{"text": "Tilgungsersatz", "correct": false, "because": "Notwendig für Rückzahlung"}, {"text": "Zinsen", "correct": false, "because": "Laufend fällig"}, {"text": "Bildschirmgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat ein Volltilgerdarlehen eine Anschlussfinanzierung?', 3, '[{"text": "Nein", "correct": true, "because": "Komplett getilgt"}, {"text": "Ja", "correct": false, "because": "Keine Restschuld"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein KfW-Darlehen frei kombinierbar ist?', 2, '[{"text": "Ja", "correct": true, "because": "Mit anderen Darlehen möglich"}, {"text": "Nein", "correct": false, "because": "Kombination üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Tilgungsrate?', 4, '[{"text": "Beeinflusst Laufzeit", "correct": true, "because": "Höher, kürzer"}, {"text": "Erhöht Zinsen", "correct": false, "because": "Zinsen sinken"}, {"text": "Ändert Zinssatz", "correct": false, "because": "Unabhängig"}]');
